"""Dart emitter: vocabulary enums and wire classes with fromJson/toJson.

No Dart SDK is needed to generate. `build_check.sh` runs `dart analyze` when one
is installed.
"""
from __future__ import annotations

from schema_model import Model, Type, camel, pascal

HEADER = """// @generated by packages/schemas/codegen/gen.py from packages/schemas/vocabulary.json and
// packages/schemas/json/*.schema.json. Do not edit; run `bash packages/schemas/codegen/gen.sh`.
"""

RESERVED = {
    "abstract", "as", "assert", "async", "await", "break", "case", "catch", "class", "const",
    "continue", "covariant", "default", "deferred", "do", "dynamic", "else", "enum", "export",
    "extends", "extension", "external", "factory", "false", "final", "finally", "for", "get", "if",
    "implements", "import", "in", "interface", "is", "late", "library", "mixin", "new", "null",
    "on", "operator", "part", "required", "rethrow", "return", "set", "static", "super", "switch",
    "sync", "this", "throw", "true", "try", "typedef", "var", "void", "while", "with", "yield",
}
ENUM_MEMBER_TAKEN = {"values", "index", "hashCode", "runtimeType", "toString", "noSuchMethod", "code", "fromJson", "toJson"}


def ident(name: str) -> str:
    n = camel(name)
    return n + "Value" if n in RESERVED else n


def member(code: str) -> str:
    n = ident(code)
    if n in ENUM_MEMBER_TAKEN:
        raise ValueError(f"enum member {code!r} collides with a reserved Dart name")
    return n


def doc(text: str, indent: str = "") -> str:
    out = []
    for line in text.strip().splitlines():
        line = line.rstrip()
        out.append(f"{indent}///{(' ' + line) if line else ''}")
    return "\n".join(out) + ("\n" if out else "")


def dart_type(t: Type) -> str:
    if t.kind == "string":
        base = "String"
    elif t.kind == "integer":
        base = "int"
    elif t.kind == "number":
        base = "double"
    elif t.kind == "boolean":
        base = "bool"
    elif t.kind == "any":
        return "Object?"
    elif t.kind == "array":
        base = f"List<{dart_type(t.item)}>"
    elif t.kind == "map":
        base = f"Map<String, {dart_type(t.item)}>"
    elif t.kind == "ref":
        base = t.name
    elif t.kind == "enum":
        base = pascal(t.name)
    else:
        raise AssertionError(t.kind)
    return base + "?" if t.nullable else base


def decode(t: Type, src: str) -> str:
    """Expression decoding the non-null JSON value `src` (dynamic) into t."""
    if t.kind == "string":
        return f"{src} as String"
    if t.kind == "integer":
        return f"{src} as int"
    if t.kind == "number":
        return f"({src} as num).toDouble()"
    if t.kind == "boolean":
        return f"{src} as bool"
    if t.kind == "any":
        return src
    if t.kind == "enum":
        return f"{pascal(t.name)}.fromJson({src} as String)"
    if t.kind == "ref":
        return f"{t.name}.fromJson({src} as Map<String, dynamic>)"
    if t.kind == "array":
        return f"({src} as List<dynamic>).map((e) => {decode_nullable(t.item, 'e')}).toList()"
    if t.kind == "map":
        return f"({src} as Map<String, dynamic>).map((k, v) => MapEntry(k, {decode_nullable(t.item, 'v')}))"
    raise AssertionError(t.kind)


def decode_nullable(t: Type, src: str) -> str:
    if t.kind == "any":
        return src
    if t.nullable:
        return f"{src} == null ? null : {decode(t, src)}"
    return decode(t, src)


def encode(t: Type, src: str) -> str:
    """Expression encoding the non-null Dart value `src`."""
    if t.kind in ("string", "integer", "number", "boolean", "any"):
        return src
    if t.kind in ("enum", "ref"):
        return f"{src}.toJson()"
    if t.kind == "array":
        return f"{src}.map((e) => {encode_nullable(t.item, 'e')}).toList()"
    if t.kind == "map":
        return f"{src}.map((k, v) => MapEntry(k, {encode_nullable(t.item, 'v')}))"
    raise AssertionError(t.kind)


def encode_nullable(t: Type, src: str) -> str:
    if t.kind in ("any",):
        return src
    if t.nullable:
        return f"{src} == null ? null : {encode(t, src)}"
    return encode(t, src)


def emit_vocabulary(model: Model) -> str:
    out = [HEADER, f"\n/// Version of packages/schemas/vocabulary.json these enums were generated from.\nconst String vocabularyVersion = '{model.vocabulary_version}';\n"]
    for axis in model.axes.values():
        name = pascal(axis.id)
        members = [member(v["code"]) for v in axis.values]
        if len(set(members)) != len(members):
            raise ValueError(f"{axis.id}: Dart member collision")
        out.append("\n" + doc(f"{axis.name_ko}: {axis.concept_ko}\n\nAxis `{axis.id}`. Unknown values throw (never a default)."))
        out.append(f"enum {name} {{\n")
        for i, v in enumerate(axis.values):
            end = ";" if i == len(axis.values) - 1 else ","
            out.append(doc(v["concept_ko"], "  "))
            out.append(f"  {member(v['code'])}('{v['code']}'){end}\n")
        out.append(f"\n  const {name}(this.code);\n\n  final String code;\n\n")
        out.append(f"  static {name} fromJson(String code) {{\n    for (final v in values) {{\n      if (v.code == code) return v;\n    }}\n")
        out.append(f"    throw FormatException('unknown {axis.id}: $code');\n  }}\n\n  String toJson() => code;\n}}\n")
    return "".join(out)


def emit_types(model: Model, structs=None, imports: str | None = None, header: str = HEADER) -> str:
    """`structs`/`imports`/`header` let emit_api reuse this for the API client."""
    if imports is None:
        imports = "\nimport 'vocabulary.dart';\n"
    out = [header, imports]
    for st in (model.structs.values() if structs is None else structs):
        out.append("\n" + doc(st.description or st.name))
        out.append(f"class {st.name} {{\n")
        for f in st.fields:
            if f.description:
                out.append(doc(f.description, "  "))
            ty = dart_type(f.type)
            if not f.required and not ty.endswith("?"):
                ty += "?"
            out.append(f"  final {ty} {ident(f.name)};\n")
        out.append(f"\n  const {st.name}({{\n")
        for f in st.fields:
            req = "required " if f.required else ""
            out.append(f"    {req}this.{ident(f.name)},\n")
        out.append("  });\n\n")
        out.append(f"  factory {st.name}.fromJson(Map<String, dynamic> json) => {st.name}(\n")
        for f in st.fields:
            key = f"json['{f.name}']"
            if f.required and not f.type.nullable:
                expr = decode(f.type, key) if f.type.kind != "any" else key
            elif f.type.kind == "any":
                expr = key
            else:
                t = f.type
                expr = f"{key} == null ? null : {decode(t, key)}"
            out.append(f"        {ident(f.name)}: {expr},\n")
        out.append("      );\n\n")
        out.append("  Map<String, dynamic> toJson() => {\n")
        for f in st.fields:
            v = ident(f.name)
            if f.required:
                out.append(f"        '{f.name}': {encode_nullable(f.type, v)},\n")
            elif f.type.kind == "any":
                out.append(f"        if ({v} != null) '{f.name}': {v},\n")
            else:
                out.append(f"        if ({v} != null) '{f.name}': {encode(f.type, v + '!')},\n")
        out.append("      };\n}\n")
    return "".join(out)


def emit_library() -> str:
    return HEADER + "\nlibrary onjeon_contracts;\n\nexport 'src/types.dart';\nexport 'src/vocabulary.dart';\n"


def emit_pubspec(version: str) -> str:
    return (
        "name: onjeon_contracts\n"
        "description: Generated ONJEON contract types (do not edit)\n"
        f"version: {version}\n"
        "publish_to: none\n"
        "environment:\n  sdk: '>=3.0.0 <4.0.0'\n"
    )


def emit_analysis_options() -> str:
    return "analyzer:\n  language:\n    strict-casts: false\n"


def emit(model: Model, version: str) -> dict:
    return {
        "pubspec.yaml": emit_pubspec(version),
        "analysis_options.yaml": emit_analysis_options(),
        "lib/onjeon_contracts.dart": emit_library(),
        "lib/src/vocabulary.dart": emit_vocabulary(model),
        "lib/src/types.dart": emit_types(model),
    }
